package android.graphics;
public class Paint { public static final int ANTI_ALIAS_FLAG = 1; public enum Style { FILL, STROKE, FILL_AND_STROKE } public enum Align { LEFT, CENTER, RIGHT } public Paint() {} public Paint(int f) {} public void setColor(int c) {} public int getColor() { return 0; } public void setStyle(Style s) {} public void setStrokeWidth(float w) {} public void setAntiAlias(boolean b) {} float textSize = 12f; public void setTextSize(float s) { textSize = s; } public float getTextSize() { return textSize; }
  public static class FontMetrics { public float top, ascent, descent, bottom, leading; }
  public static class FontMetricsInt { public int top, ascent, descent, bottom, leading; }
  public FontMetrics getFontMetrics() { FontMetrics m = new FontMetrics(); getFontMetrics(m); return m; }
  public float getFontMetrics(FontMetrics m) { if (m != null) { m.top = -1.06f * textSize; m.ascent = -0.93f * textSize; m.descent = 0.24f * textSize; m.bottom = 0.27f * textSize; m.leading = 0; } return 1.17f * textSize; }
  public FontMetricsInt getFontMetricsInt() { FontMetricsInt m = new FontMetricsInt(); m.top = Math.round(-1.06f * textSize); m.ascent = Math.round(-0.93f * textSize); m.descent = Math.round(0.24f * textSize); m.bottom = Math.round(0.27f * textSize); return m; }
  public float ascent() { return -0.93f * textSize; } public float descent() { return 0.24f * textSize; } public void setAlpha(int a) {} public void setTypeface(Typeface t) {} public void setTextAlign(Align a) {} public float measureText(String s) { return s == null ? 0 : s.length() * textSize * 0.9f; } public void setFakeBoldText(boolean b) {} public void setStrokeCap(Object c) {} }